package com.simplespec;

import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Perspective;
import net.runelite.api.Player;
import net.runelite.api.Point;
import net.runelite.api.coords.LocalPoint;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * Draws the meter attached to the local player, level with the overhead health bar by default.
 * Offsets are in game units rather than pixels, so the meter keeps its place relative to the
 * character when the camera zooms. Used when the position mode is set to on character.
 */
class SpecEchelonAnchoredOverlay extends SpecEchelonOverlay
{
	// Distance used to measure how many screen pixels one game unit covers at the player.
	private static final int SCALE_PROBE = 128;
	// Fixed height of the health bar above the ground, in game units. The player's own model
	// height is not used because it changes with held items (a halberd is taller than a dagger).
	private static final int HEALTH_BAR_HEIGHT = 210;

	@Inject
	SpecEchelonAnchoredOverlay(Client client, SpecEchelonPlugin plugin, SpecEchelonConfig config)
	{
		super(client, plugin, config);
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
		setMovable(false);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (config.positionMode() != SpecEchelonConfig.PositionMode.ON_CHARACTER)
		{
			return null;
		}

		Player local = client.getLocalPlayer();
		if (local == null)
		{
			return null;
		}

		LocalPoint coord = local.getLocalLocation();
		int worldView = local.getWorldView().getId();
		int groundZ = Perspective.getFootprintTileHeight(client, coord, local.getWorldView().getPlane(), local.getFootprintSize());
		// A world height scales with zoom just like the character does.
		int z = groundZ - (HEALTH_BAR_HEIGHT + config.characterOffsetY());

		Point anchor = Perspective.localToCanvas(client, worldView, coord.getX(), coord.getY(), z);
		Point alongX = Perspective.localToCanvas(client, worldView, coord.getX() + SCALE_PROBE, coord.getY(), z);
		Point alongY = Perspective.localToCanvas(client, worldView, coord.getX(), coord.getY() + SCALE_PROBE, z);
		if (anchor == null || alongX == null || alongY == null)
		{
			return null;
		}

		// Screen pixels per game unit at the player's distance from the camera. Using only the
		// screen x of two perpendicular ground directions keeps this independent of camera
		// rotation and pitch, so the horizontal offset grows and shrinks with zoom.
		double pixelsPerUnit = Math.hypot(alongX.getX() - anchor.getX(), alongY.getX() - anchor.getX()) / SCALE_PROBE;

		int x = anchor.getX() + (int) Math.round(config.characterOffsetX() * pixelsPerUnit);
		int y = anchor.getY() - meterHeight() / 2;

		graphics.translate(x, y);
		renderMeter(graphics);
		graphics.translate(-x, -y);
		return null;
	}
}

package com.simplespec;

import java.awt.Color;
import net.runelite.client.config.Alpha;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Range;
import net.runelite.client.config.Units;

@ConfigGroup(SpecEchelonConfig.GROUP)
public interface SpecEchelonConfig extends Config
{
	String GROUP = "simplespec";

	enum Orientation
	{
		HORIZONTAL,
		VERTICAL
	}

	enum PositionMode
	{
		FREE("Free (drag anywhere)"),
		ON_CHARACTER("On character");

		private final String label;

		PositionMode(String label)
		{
			this.label = label;
		}

		@Override
		public String toString()
		{
			return label;
		}
	}

	@ConfigSection(
		name = "Colors",
		description = "Meter colors",
		position = 0
	)
	String colorSection = "colors";

	@ConfigSection(
		name = "Layout",
		description = "Meter size and layout",
		position = 1
	)
	String layoutSection = "layout";

	@ConfigSection(
		name = "Position",
		description = "Where the meter is drawn",
		position = 2
	)
	String positionSection = "position";

	@Alpha
	@ConfigItem(
		keyName = "tier1Color",
		name = "Tier 1 color",
		description = "Color for specs 1 to 3",
		section = colorSection,
		position = 0
	)
	default Color tier1Color()
	{
		return new Color(255, 214, 0);
	}

	@Alpha
	@ConfigItem(
		keyName = "tier2Color",
		name = "Tier 2 color",
		description = "Color for specs 4 to 6",
		section = colorSection,
		position = 1
	)
	default Color tier2Color()
	{
		return new Color(220, 40, 40);
	}

	@Alpha
	@ConfigItem(
		keyName = "tier3Color",
		name = "Tier 3 color",
		description = "Color for specs 7 to 9",
		section = colorSection,
		position = 2
	)
	default Color tier3Color()
	{
		return new Color(160, 60, 220);
	}

	@Alpha
	@ConfigItem(
		keyName = "emptyColor",
		name = "Empty slot color",
		description = "Color for slots with no spec",
		section = colorSection,
		position = 3
	)
	default Color emptyColor()
	{
		return new Color(40, 40, 40, 160);
	}

	@Range(min = 10, max = 100)
	@Units(Units.PERCENT)
	@ConfigItem(
		keyName = "opacity",
		name = "Opacity",
		description = "Opacity of the whole meter, including outlines and the label. 100% is fully solid",
		section = colorSection,
		position = 4
	)
	default int opacity()
	{
		return 100;
	}

	@Range(min = 4, max = 60)
	@ConfigItem(
		keyName = "pipWidth",
		name = "Pip width",
		description = "Width of each slot in pixels",
		section = layoutSection,
		position = 0
	)
	default int pipWidth()
	{
		return 14;
	}

	@Range(min = 4, max = 60)
	@ConfigItem(
		keyName = "pipHeight",
		name = "Pip height",
		description = "Height of each slot in pixels",
		section = layoutSection,
		position = 1
	)
	default int pipHeight()
	{
		return 20;
	}

	@Range(max = 20)
	@ConfigItem(
		keyName = "pipSpacing",
		name = "Spacing",
		description = "Gap between slots in pixels",
		section = layoutSection,
		position = 2
	)
	default int pipSpacing()
	{
		return 3;
	}

	@ConfigItem(
		keyName = "orientation",
		name = "Orientation",
		description = "Lay the slots out horizontally or vertically",
		section = layoutSection,
		position = 3
	)
	default Orientation orientation()
	{
		return Orientation.HORIZONTAL;
	}

	@ConfigItem(
		keyName = "positionMode",
		name = "Position",
		description = "Drag the meter anywhere, or attach it to your character next to the health bar",
		section = positionSection,
		position = 0
	)
	default PositionMode positionMode()
	{
		return PositionMode.FREE;
	}

	@Range(min = -500, max = 500)
	@ConfigItem(
		keyName = "characterOffsetX",
		name = "Horizontal offset",
		description = "On character only. Moves the meter right (positive) or left (negative) of your character,"
			+ " in game units (128 is one tile), so it keeps its place when you zoom",
		section = positionSection,
		position = 1
	)
	default int characterOffsetX()
	{
		return 60;
	}

	@Range(min = -500, max = 500)
	@ConfigItem(
		keyName = "characterOffsetY",
		name = "Vertical offset",
		description = "On character only. Moves the meter up (positive) or down (negative) from the health bar,"
			+ " in game units (128 is one tile), so it keeps its place when you zoom",
		section = positionSection,
		position = 2
	)
	default int characterOffsetY()
	{
		return 0;
	}

	@ConfigItem(
		keyName = "showPartialProgress",
		name = "Show partial progress",
		description = "Fill the next slot proportionally toward the next spec",
		position = 3
	)
	default boolean showPartialProgress()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showTextLabel",
		name = "Show text label",
		description = "Show the exact number of specs next to the meter",
		position = 4
	)
	default boolean showTextLabel()
	{
		return false;
	}

	@ConfigItem(
		keyName = "highlightAdrenaline",
		name = "Highlight adrenaline",
		description = "Draw an outline around the meter while Liquid Adrenaline is active",
		position = 5
	)
	default boolean highlightAdrenaline()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showNextSpecTimer",
		name = "Show next spec timer",
		description = "Show the seconds until your next special attack is available, next to the meter",
		position = 6
	)
	default boolean showNextSpecTimer()
	{
		return false;
	}

	@Alpha
	@ConfigItem(
		keyName = "nextSpecTimerColor",
		name = "Timer text color",
		description = "Color of the next spec timer text",
		position = 7
	)
	default Color nextSpecTimerColor()
	{
		return Color.WHITE;
	}
}

package com.simplespec;

import java.awt.AlphaComposite;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Composite;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.RenderingHints;
import java.awt.Shape;
import java.awt.Stroke;
import java.awt.geom.RoundRectangle2D;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.TextComponent;

class SpecEchelonOverlay extends Overlay
{
	private static final int SLOT_COUNT = 3;
	private static final int SPECS_PER_TIER = 3;
	private static final int ARC = 6;
	// Space reserved around the slots for the adrenaline outline, so toggling it does not shift the meter.
	private static final int PADDING = 3;
	private static final int LABEL_GAP = 4;
	private static final Color OUTLINE_COLOR = new Color(0, 0, 0, 200);
	private static final Color ADRENALINE_COLOR = new Color(110, 230, 140, 220);
	private static final Stroke ADRENALINE_STROKE = new BasicStroke(1.5f);

	final Client client;
	final SpecEchelonConfig config;
	private final SpecEchelonPlugin plugin;
	private final TextComponent label = new TextComponent();

	@Inject
	SpecEchelonOverlay(Client client, SpecEchelonPlugin plugin, SpecEchelonConfig config)
	{
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.BOTTOM_RIGHT);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (config.positionMode() != SpecEchelonConfig.PositionMode.FREE)
		{
			return null;
		}

		return renderMeter(graphics);
	}

	/**
	 * Height of the slots plus outline padding, without the text label.
	 */
	int meterHeight()
	{
		final boolean vertical = config.orientation() == SpecEchelonConfig.Orientation.VERTICAL;
		final int h = config.pipHeight();
		return (vertical ? SLOT_COUNT * h + (SLOT_COUNT - 1) * config.pipSpacing() : h) + 2 * PADDING;
	}

	/**
	 * Draws the meter with its top left corner at the graphics origin.
	 */
	Dimension renderMeter(Graphics2D graphics)
	{
		if (client.getGameState() != GameState.LOGGED_IN || plugin.getWeapon() == null)
		{
			return null;
		}

		final int totalSpecs = plugin.getTotalSpecs();
		final float partial = config.showPartialProgress() ? plugin.getPartialProgress() : 0f;
		final Color[] tierColors = {config.tier1Color(), config.tier2Color(), config.tier3Color()};
		final boolean vertical = config.orientation() == SpecEchelonConfig.Orientation.VERTICAL;
		final int w = config.pipWidth();
		final int h = config.pipHeight();
		final int gap = config.pipSpacing();

		final int meterWidth = (vertical ? w : SLOT_COUNT * w + (SLOT_COUNT - 1) * gap) + 2 * PADDING;
		final int meterHeight = meterHeight();

		graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		// Fade everything drawn below by the opacity setting, then restore it for other overlays.
		final Composite oldComposite = graphics.getComposite();
		graphics.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, config.opacity() / 100f));

		for (int i = 0; i < SLOT_COUNT; i++)
		{
			// Slot 0 is leftmost when horizontal and bottommost when vertical.
			int x = PADDING + (vertical ? 0 : i * (w + gap));
			int y = PADDING + (vertical ? (SLOT_COUNT - 1 - i) * (h + gap) : 0);
			Shape slot = new RoundRectangle2D.Float(x, y, w, h, ARC, ARC);

			// Higher tiers cover lower ones from the left, like a fighting game super meter.
			graphics.setColor(totalSpecs > i
				? tierColors[(totalSpecs - 1 - i) / SPECS_PER_TIER]
				: config.emptyColor());
			graphics.fill(slot);

			// The next spec lands in slot (totalSpecs % 3), drawn in its own tier color.
			if (partial > 0f && totalSpecs < SpecEchelonPlugin.MAX_SPECS && i == totalSpecs % SLOT_COUNT)
			{
				Shape oldClip = graphics.getClip();
				graphics.clip(slot);
				graphics.setColor(tierColors[totalSpecs / SPECS_PER_TIER]);
				if (vertical)
				{
					int fill = Math.round(h * partial);
					graphics.fillRect(x, y + h - fill, w, fill);
				}
				else
				{
					graphics.fillRect(x, y, Math.round(w * partial), h);
				}
				graphics.setClip(oldClip);
			}

			graphics.setColor(OUTLINE_COLOR);
			graphics.draw(slot);
		}

		if (config.highlightAdrenaline() && plugin.isAdrenalineActive())
		{
			Stroke oldStroke = graphics.getStroke();
			graphics.setStroke(ADRENALINE_STROKE);
			graphics.setColor(ADRENALINE_COLOR);
			graphics.draw(new RoundRectangle2D.Float(1, 1, meterWidth - 2, meterHeight - 2, ARC + 4, ARC + 4));
			graphics.setStroke(oldStroke);
		}

		Dimension size = new Dimension(meterWidth, meterHeight);
		final String timerText = config.showNextSpecTimer() ? plugin.getNextSpecText() : null;

		if (config.showTextLabel() || timerText != null)
		{
			graphics.setFont(FontManager.getRunescapeSmallFont());
			if (config.showTextLabel())
			{
				size = drawText(graphics, String.valueOf(totalSpecs), Color.WHITE, vertical, meterWidth, meterHeight, size);
			}
			if (timerText != null)
			{
				size = drawText(graphics, timerText, config.nextSpecTimerColor(), vertical, meterWidth, meterHeight, size);
			}
		}

		graphics.setComposite(oldComposite);
		return size;
	}

	/**
	 * Draws text after everything drawn so far, below it when vertical or to the right of it when
	 * horizontal, and returns the new overall size.
	 */
	private Dimension drawText(Graphics2D graphics, String text, Color color, boolean vertical,
		int meterWidth, int meterHeight, Dimension size)
	{
		FontMetrics metrics = graphics.getFontMetrics();
		int textWidth = metrics.stringWidth(text);

		Point position;
		Dimension newSize;
		if (vertical)
		{
			// Centered below the meter.
			position = new Point((meterWidth - textWidth) / 2, size.height + LABEL_GAP + metrics.getAscent());
			newSize = new Dimension(Math.max(size.width, textWidth), size.height + LABEL_GAP + metrics.getHeight());
		}
		else
		{
			// Vertically centered to the right of the meter.
			position = new Point(size.width + LABEL_GAP, (meterHeight + metrics.getAscent() - metrics.getDescent()) / 2);
			newSize = new Dimension(size.width + LABEL_GAP + textWidth, size.height);
		}

		label.setText(text);
		label.setColor(color);
		label.setPosition(position);
		label.render(graphics);
		return newSize;
	}
}

package com.simplespec;

import com.google.common.collect.ImmutableSet;
import com.google.inject.Provides;
import java.util.Set;
import javax.inject.Inject;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.Constants;
import net.runelite.api.EquipmentInventorySlot;
import net.runelite.api.GameState;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.Player;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.events.ScriptPostFired;
import net.runelite.api.events.VarbitChanged;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

@Slf4j
@PluginDescriptor(
	name = "SimpleSpec",
	description = "Shows how many special attacks you can use based on spec energy, weapon, and ToA Liquid Adrenaline",
	tags = {"special", "spec", "attack", "energy", "pvm", "toa", "raids"}
)
public class SpecEchelonPlugin extends Plugin
{
	/**
	 * Liquid Adrenaline active flag, treated as active while above 0.
	 * UNVERIFIED: confirm with Developer Tools > Var Inspector by drinking a dose in ToA.
	 * RuneLite's Timers and Buffs plugin uses this varbit to end its Liquid Adrenaline timer.
	 */
	static final int LIQUID_ADRENALINE_VARBIT = VarbitID.TOA_MIDRAIDLOOT_ENERGY_ACTIVE;

	/*
	 * Overly Draining has no varbit or varp. Var Inspector showed no change when toggling it,
	 * creating a party, or entering the raid (only the total raid level changes). Like the Tombs
	 * of Amascut hub plugin's invocation presets, it is read from the party screen's invocation
	 * list in the lobby and remembered for the raid.
	 */
	// Party screen scripts (no gameval constants exist): building the screen, and toggling its panel.
	private static final int SCRIPT_BUILD_TOA_PARTY_INTERFACE = 6729;
	private static final int SCRIPT_TOA_PARTY_TOGGLE_REWARD_PANEL = 6732;
	// Each invocation takes 3 children in the list, and Overly Draining is the 20th invocation.
	private static final int OVERLY_DRAINING_CHILD = 19 * 3;
	// An invocation's click handler argument at this index is 1 while it is selected.
	private static final int INVOCATION_SELECTED_ARG = 3;

	/**
	 * Tombs of Amascut instance regions. The adrenaline varbit can linger after leaving, and the
	 * remembered Overly Draining selection stays set, so both only count while in one of these.
	 */
	private static final Set<Integer> TOA_REGIONS = ImmutableSet.of(
		14160, // Nexus
		15698, // Path of Crondis
		15700, // Zebak
		14162, // Path of Scabaras
		14164, // Kephri
		15186, // Path of Apmeken
		15188, // Ba-Ba
		14674, // Path of Het
		14676, // Akkha
		15184, // Wardens, first and second phase
		15696, // Wardens, final phase
		14672  // Tomb
	);

	static final int MAX_SPECS = 9;

	// Spec energy is stored in tenths of a percent.
	private static final int MAX_ENERGY = 1000;
	// Energy restored per regen step, 10%.
	private static final int REGEN_AMOUNT = 100;
	// Ticks per regen step, halved while wearing the Lightbearer.
	private static final int SPEC_REGEN_TICKS = 50;

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private SpecEchelonOverlay overlay;

	@Inject
	private SpecEchelonAnchoredOverlay anchoredOverlay;

	@Getter
	private SpecWeapon weapon;

	/**
	 * Liquid Adrenaline, only while inside the Tombs of Amascut.
	 */
	@Getter
	private boolean adrenalineActive;

	// Raw states, before the ToA region check.
	private boolean adrenalineVarActive;
	// Overly Draining as last seen on the party screen.
	private boolean overlyDrainingSelected;

	private boolean inToa;

	/**
	 * Raw spec energy in tenths of a percent, 0 to 1000.
	 */
	private int specEnergy;

	@Getter
	private int totalSpecs;

	/**
	 * Progress toward the next spec, 0.0 to 1.0.
	 */
	@Getter
	private float partialProgress;

	// Regen cycle tracking, mirroring RuneLite's Regeneration Meter plugin.
	private int ticksSinceSpecRegen;
	private boolean wearingLightbearer;
	// Energy seen on the previous game tick, or -1 when unknown.
	private int lastTickEnergy = -1;

	/**
	 * Time until the next spec is available, such as "12s", or null when the timer is hidden.
	 */
	@Getter
	private String nextSpecText;

	@Override
	protected void startUp()
	{
		// Only one of these draws at a time, depending on the position mode.
		overlayManager.add(overlay);
		overlayManager.add(anchoredOverlay);
		// Pick up the current state so the meter is correct without re-equipping.
		clientThread.invoke(this::refreshAll);
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(overlay);
		overlayManager.remove(anchoredOverlay);
		weapon = null;
		adrenalineVarActive = false;
		overlyDrainingSelected = false;
		inToa = false;
		specEnergy = 0;
		ticksSinceSpecRegen = 0;
		wearingLightbearer = false;
		lastTickEnergy = -1;
		recompute();
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		GameState state = event.getGameState();
		if (state == GameState.LOGGED_IN)
		{
			refreshAll();
		}
		else if (state == GameState.HOPPING || state == GameState.LOGIN_SCREEN)
		{
			// Same reset as the Regeneration Meter, the regen cycle restarts on a new session.
			ticksSinceSpecRegen = 0;
			lastTickEnergy = -1;
		}
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		if (event.getContainerId() == InventoryID.WORN)
		{
			updateWeapon(event.getItemContainer());
			updateLightbearer(event.getItemContainer());
			recompute();
		}
	}

	@Subscribe
	public void onVarbitChanged(VarbitChanged event)
	{
		if (event.getVarpId() == VarPlayerID.SA_ENERGY || event.getVarbitId() == LIQUID_ADRENALINE_VARBIT)
		{
			readVars();
			recompute();
		}
	}

	@Subscribe
	public void onScriptPostFired(ScriptPostFired event)
	{
		int scriptId = event.getScriptId();
		if (scriptId == SCRIPT_BUILD_TOA_PARTY_INTERFACE || scriptId == SCRIPT_TOA_PARTY_TOGGLE_REWARD_PANEL)
		{
			readOverlyDraining();
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		boolean nowInToa = isInToa();
		if (nowInToa != inToa)
		{
			log.debug("Tombs of Amascut region {}", nowInToa ? "entered" : "left");
			inToa = nowInToa;
		}

		specEnergy = client.getVarpValue(VarPlayerID.SA_ENERGY);
		updateRegenCycle();
		recompute();
	}

	private void refreshAll()
	{
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}

		ItemContainer equipment = client.getItemContainer(InventoryID.WORN);
		updateWeapon(equipment);
		updateLightbearer(equipment);
		inToa = isInToa();
		readVars();
		recompute();
	}

	private void readVars()
	{
		specEnergy = client.getVarpValue(VarPlayerID.SA_ENERGY);
		adrenalineVarActive = client.getVarbitValue(LIQUID_ADRENALINE_VARBIT) > 0;
	}

	/**
	 * Reads whether Overly Draining is selected on the ToA party screen. Only reads the widget,
	 * it never changes it. The result is kept until the screen is shown again.
	 */
	private void readOverlyDraining()
	{
		Widget list = client.getWidget(InterfaceID.ToaPartydetails.INVOCATIONS_CONTENT);
		Widget invocation = list == null ? null : list.getChild(OVERLY_DRAINING_CHILD);
		if (invocation == null)
		{
			return;
		}

		Object[] args = invocation.getOnOpListener();
		if (args == null || args.length <= INVOCATION_SELECTED_ARG || !(args[INVOCATION_SELECTED_ARG] instanceof Integer))
		{
			return;
		}

		boolean selected = (Integer) args[INVOCATION_SELECTED_ARG] == 1;
		if (selected != overlyDrainingSelected)
		{
			log.debug("Overly Draining {}", selected ? "selected" : "deselected");
			overlyDrainingSelected = selected;
			recompute();
		}
	}

	private boolean isInToa()
	{
		Player local = client.getLocalPlayer();
		if (local == null)
		{
			return false;
		}

		// ToA is instanced, so map the instance tile back to its template region.
		WorldPoint location = WorldPoint.fromLocalInstance(client, local.getLocalLocation());
		return location != null && TOA_REGIONS.contains(location.getRegionID());
	}

	private void updateWeapon(ItemContainer equipment)
	{
		Item item = equipment == null ? null : equipment.getItem(EquipmentInventorySlot.WEAPON.getSlotIdx());
		SpecWeapon newWeapon = item == null ? null : SpecWeapon.forItemId(item.getId());
		if (newWeapon != weapon)
		{
			log.debug("Tracked weapon changed to {}", newWeapon == null ? "none" : newWeapon.getDisplayName());
			weapon = newWeapon;
		}
	}

	private void updateLightbearer(ItemContainer equipment)
	{
		Item ring = equipment == null ? null : equipment.getItem(EquipmentInventorySlot.RING.getSlotIdx());
		boolean hasLightbearer = ring != null
			&& (ring.getId() == ItemID.LIGHTBEARER || ring.getId() == ItemID.BR_LIGHTBEARER);
		if (hasLightbearer == wearingLightbearer)
		{
			return;
		}

		// Same as the Regeneration Meter: swapping the Lightbearer keeps the time until the next
		// regen if under 25 ticks remain. Taking it off always restarts the 50 tick cycle.
		ticksSinceSpecRegen = Math.max(0, ticksSinceSpecRegen - SPEC_REGEN_TICKS / 2);
		wearingLightbearer = hasLightbearer;
	}

	private int ticksPerSpecRegen()
	{
		return wearingLightbearer ? SPEC_REGEN_TICKS / 2 : SPEC_REGEN_TICKS;
	}

	/**
	 * Advances the regen cycle by one game tick, like the Regeneration Meter, and also resyncs the
	 * cycle whenever a natural regen step is seen so the timer corrects itself after logging in.
	 */
	private void updateRegenCycle()
	{
		if (specEnergy >= MAX_ENERGY)
		{
			// The recharge does not tick while at 100%.
			ticksSinceSpecRegen = 0;
		}
		else if (lastTickEnergy >= 0 && specEnergy - lastTickEnergy == REGEN_AMOUNT)
		{
			// Only a regen step adds exactly 10%, so a regen just happened. Potions restore other
			// amounts and do not move the cycle.
			ticksSinceSpecRegen = 0;
		}
		else
		{
			ticksSinceSpecRegen = (ticksSinceSpecRegen + 1) % ticksPerSpecRegen();
		}
		lastTickEnergy = specEnergy;
	}

	private void recompute()
	{
		adrenalineActive = inToa && adrenalineVarActive;

		if (weapon == null)
		{
			totalSpecs = 0;
			partialProgress = 0f;
			nextSpecText = null;
			return;
		}

		// Work in tenths of a percent like the energy varp, so a halved 25% cost stays
		// exact at 125 (12.5%) instead of rounding down to 12%.
		// Overly Draining makes every spec cost 100%, replacing the weapon's own cost.
		int baseCost = inToa && overlyDrainingSelected ? MAX_ENERGY : weapon.getBaseCost() * 10;
		// Liquid Adrenaline then halves whichever cost applies, so Overly Draining with
		// adrenaline costs 50% per spec.
		int activeCost = adrenalineActive ? baseCost / 2 : baseCost;

		int specs = specEnergy / activeCost;
		if (specs >= MAX_SPECS)
		{
			totalSpecs = MAX_SPECS;
			partialProgress = 0f;
		}
		else
		{
			totalSpecs = specs;
			partialProgress = (specEnergy % activeCost) / (float) activeCost;
		}

		updateNextSpecText(activeCost);
	}

	private void updateNextSpecText(int activeCost)
	{
		if (specEnergy >= MAX_ENERGY || totalSpecs >= MAX_SPECS)
		{
			nextSpecText = null;
			return;
		}

		int ticksPerRegen = ticksPerSpecRegen();
		// Energy still missing for the next spec, and how many 10% regen steps cover it.
		int energyNeeded = activeCost - (specEnergy % activeCost);
		int regenSteps = (energyNeeded + REGEN_AMOUNT - 1) / REGEN_AMOUNT;
		// The rest of the current step, plus every remaining full step.
		int ticks = (ticksPerRegen - ticksSinceSpecRegen) + (regenSteps - 1) * ticksPerRegen;
		// 0.6 seconds per tick, rounded up so the timer never reads 0s early.
		int seconds = (ticks * Constants.GAME_TICK_LENGTH + 999) / 1000;
		nextSpecText = seconds + "s";
	}

	@Provides
	SpecEchelonConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(SpecEchelonConfig.class);
	}
}

